def parse_events_log(log_content: str) -> dict:
    """
    Parses the log content string into a dictionary mapping job_id to a list of events.
    Example log line: 'job=a running at=10; job=a completed at=20'
    Example output: {'a': [{'state': 'running', 'at': 10}, {'state': 'completed', 'at': 20}, ...]}
    """
    events = {}
    if not log_content:
        return events

    # Split by job; state and time are captured in the regex
    # Regex captures: job_id (group 1), state (group 2), time (group 3)
    # It handles both 'running' and 'completed' states mentioned in the example log.
    pattern = re.compile(r"job=([^ ]+)\s+(running|completed)\s+at=(\d+)")

    for line in log_content.splitlines():
        if not line.strip():
            continue

        matches = pattern.findall(line)

        for job_id, state, time_str in matches:
            try:
                time_at = int(time_str)
                if job_id not in events:
                    events[job_id] = []

                events[job_id].append({
                    'state': state,
                    'at': time_at
                })
            except ValueError:
                # Should not happen with valid input, but good practice
                pass
    return events

def is_stuck(events: dict, now: int, grace: int) -> list[str]:
    """
    Returns sorted job_ids whose latest event is running and older than grace seconds.
    """
    stuck_job_ids = []

    for job_id, history in events.items():
        latest_event = None

        # Find the event with the latest timestamp for this job
        for event in history:
            if latest_event is None or event['at'] > latest_event['at']:
                latest_event = event

        if latest_event is None:
            continue

        state = latest_event['state']
        time_at = latest_event['at']

        # 1. queued and completed are never stuck.
        if state in ['queued', 'completed']:
            continue

        # 2. Equal to grace is not stuck. Must be strictly older than grace seconds.
        # Stuck condition: time_at < now - grace
        threshold_time = now - grace

        if time_at < threshold_time:
            stuck_job_ids.append(job_id)

    return sorted(stuck_job_ids)

